import { getUserContext } from '@/lib/supabase/user-context'
import { createClient } from '@/lib/supabase/server'
import { PortalHeader, PortalTable, EmptyState, StatusPill, formatDate } from '@/components/portal/portal-shell'

export default async function PortalResultsPage() { const context = await getUserContext(); const supabase = await createClient(); const { data: profile } = await supabase.from('profiles').select('student_id').eq('id', context!.userId).maybeSingle(); const { data: links } = await supabase.from('parent_student_links').select('student_id').eq('parent_profile_id', context!.userId); const ids = [...new Set([...(links ?? []).map((x) => x.student_id), ...(profile?.student_id ? [profile.student_id] : [])])]; const { data } = ids.length ? await supabase.from('results').select('student_id,marks_obtained,remarks,tests(name,subject,test_date,max_marks)').in('student_id', ids).order('created_at', { ascending: false }) : { data: [] as any[] }; return <><PortalHeader title="Results" description="Published test results and academic progress." />{data?.length ? <PortalTable headers={['Test', 'Subject', 'Date', 'Marks', 'Remarks']} rows={data.map((row: any, index) => { const test = row.tests; const percentage = test?.max_marks ? Math.round((Number(row.marks_obtained) / Number(test.max_marks)) * 100) : 0; return [<span key={index} className="font-medium">{test?.name ?? 'Test'}</span>, test?.subject ?? '—', formatDate(test?.test_date), <StatusPill key={`score-${index}`}>{row.marks_obtained}/{test?.max_marks ?? '—'} · {percentage}%</StatusPill>, row.remarks || '—'] })} /> : <EmptyState text="Published results will appear here." />}</> }
